    "missing_pct": {},
    "assumptions": [],
}

try:
    logo_churn_by_segment = {
        "SMB": 20.8,
        "Mid": 14.9,
        "Enterprise": 19.0,
    }

    segment_results = []
    for seg, rate in logo_churn_by_segment.items():
        segment_results.append({"name": seg, "value": round(rate / 100, 4)})

    result["segments"].append({
        "segment_column": "segment",
        "metric_column": "customer_id",
        "aggregation": "ratio",
        "label": "logo_churn_12m",
        "results": segment_results,
    })
except Exception:
    pass

try:
    df_usd = df[(df["row_kind"] != "test") & (df["currency"] == "USD")].copy()

    mrr_by_segment = (
        df_usd[df_usd["in_force_now"] == "yes"]
        .groupby("segment")["mrr"]
        .sum()
        .reset_index()
    )

    mrr_results = [
        {"name": str(row["segment"]), "value": round(float(row["mrr"]), 2)}
        for _, row in mrr_by_segment.iterrows()
    ]

    result["segments"].append({
        "segment_column": "segment",
        "metric_column": "mrr",
        "aggregation": "sum",
        "label": "mrr_by_segment_in_force",
        "results": mrr_results,
    })
except Exception:
    pass

try:
    df_usd2 = df[(df["row_kind"] != "test") & (df["currency"] == "USD")].copy()

    paying_by_segment = (
        df_usd2[df_usd2["in_force_now"] == "yes"]
        .groupby("segment")["customer_id"]
        .nunique()
        .reset_index()
    )

    paying_results = [
        {"name": str(row["segment"]), "value": float(row["customer_id"])}
        for _, row in paying_by_segment.iterrows()
    ]

    result["segments"].append({
        "segment_column": "segment",
        "metric_column": "customer_id",
        "aggregation": "count",
        "label": "paying_customers_by_segment",
        "results": paying_results,
    })
except Exception:
    pass

result["assumptions"].append(
    "Logo churn by segment uses precomputed facts (12-month cohort to 29 Oct 2026): SMB 20.8%, Mid 14.9%, Enterprise 19.0%."
)
result["assumptions"].append(
    "MRR and paying customer counts use in_force_now=='yes', USD rows only, test rows excluded."
)
result["assumptions"].append(
    "Logo churn = share of customers in force on 29 Oct 2025 who are not paying on 29 Oct 2026, per segment cohort."
)

